style.css:
/* Galaksi Temalı YouTube Kaydırma Çubuğu */
::-webkit-scrollbar {
    width: 10px;
    background: #000; /* Arka plan rengini uzay boşluğu gibi siyah yap */
}

::-webkit-scrollbar-thumb {
    background: linear-gradient(45deg, #ff007f, #ff8c00, #ffd700, #4b0082, #9400d3); /* Galaksi renkleri */
    border-radius: 10px; /* Çubuğa yuvarlak hatlar ekle */
    border: 2px solid #000; /* Çerçeve efekti */
}

::-webkit-scrollbar-thumb:hover {
    background: linear-gradient(45deg, #ffd700, #4b0082, #9400d3, #ff007f, #ff8c00); /* Hover efekti */
}

::-webkit-scrollbar-track {
    background: radial-gradient(circle, #2c2c54, #000); /* Radial galaksi efekti */
}
